    rollbackExecution: {
        parameters: {
            query?: never;
            header?: never;
            path: {
                /** @description The execution id, as `GET /changes` reports it. */
                id: string;
            };
            cookie?: never;
        };
        requestBody?: {
            content: {
                "application/json": components["schemas"]["RollbackRequest"];
            };
        };
        responses: {
            /**
             * @description The cluster accepted the change. An empty `incidentState` means the outcome
             *     could not be recorded and the recovery sweep will finish it — render the
             *     absence, never a state of `""`.
             */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["RollbackResponse"];
                };
            };
            400: components["responses"]["BadRequest"];
            401: components["responses"]["Unauthorized"];
            403: components["responses"]["Forbidden"];
            /** @description No such execution. */
            404: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/problem+json": components["schemas"]["Problem"];
                };
            };
            /**
             * @description Six structurally distinct refusals share this status, each with its own
             *     `type`. Four are about the execution or the incident:
             *     `.../invalid-state` (the execution did not succeed, or another change is in
             *     flight on this incident right now), `.../already-rolled-back`,
             *     `.../nothing-to-undo` (the field is already where the undo would put it —
             *     usually a GitOps controller's next sync having reverted ARGUS), and
             *     `.../undo-value-changed` (something else moved the field since; re-send with
             *     `confirmValueChanged: true` if you have checked and still want the original
             *     value restored — the acknowledgement is audited).
             *
             *     The other two are the same guardrail refusals `POST /incidents/{id}/approve`
             *     makes, for the same reasons: `.../scale-from-zero-refused` and
             *     `.../gitops-managed-refused`, each carrying `confirmationToken` as an
             *     extension member to echo back with the matching `confirm*` flag.
             */
            409: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/problem+json": components["schemas"]["Problem"];
                };
            };
            /**
             * @description `.../no-rollback-recorded` — this action type has no undo (expected for a
             *     workload restart: the pods it replaced are already gone) — or
             *     `.../invalid-state` when the stored compensating action does not decode.
             */
            422: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/problem+json": components["schemas"]["Problem"];
                };
            };
            500: components["responses"]["InternalError"];
            /** @description `.../remediation-execution-failed` — the undo could not be applied. */
            502: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/problem+json": components["schemas"]["Problem"];
                };
            };
            /**
             * @description `.../cluster-unreachable` — the cluster has no live agent connection, or
             *     ARGUS could not read the current value and refused to apply an undo blind.
             */
            503: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/problem+json": components["schemas"]["Problem"];
                };
            };
        };
    };
